First, let me fix pricing.js allocate:

```js
function allocate(totalCents, weights) {
  const sum = weights.reduce((a, b) => a + b, 0);
  if (sum === 0) return weights.map(() => 0);
  const parts = weights.map((w) => Math.floor((totalCents * w) / sum));
  let remainder = totalCents - parts.reduce((a, b) => a + b, 0);
  if (remainder === 0) return parts;
  // Find the part with the largest fractional remainder; ties → earliest
  let bestIdx = 0;
  let maxRemainderNum = -1;
  for (let i = 0; i < weights.length; i++) {
    const remNum = (totalCents * weights[i]) % sum;
    if (remNum > maxRemainderNum) {
      maxRemainderNum = remNum;
      bestIdx = i;
    }
  }
  parts[bestIdx]++;
  return parts;
}
```

