      for (const l of merged) this.inventory.reserve(l.sku, l.qty);
      reserved = true;
    } catch (e) {
      // If reservation failed, release any stock already reserved in this attempt
      for (const l of reserved) this.inventory.release(l.sku, l.qty);
      throw e;
