    if (order.status !== 'placed' && order.status !== 'partially_refunded') throw new RefundError('Order is not refundable');

    // Validate date
    if (typeof date !== 'string' || !DATE_RE.test(date)) throw new RefundError('Invalid refund date');
    if (date < order.date) throw new RefundError('Refund date cannot be earlier than order date');

    // Merge items
    const itemMap = new Map();
    for (const it of items) {
      if (!Number.isInteger(it.qty) || it.qty <= 0) throw new RefundError(`Invalid refund quantity for ${it.sku}`);
      itemMap.set(it.sku, (itemMap.get(it.sku) ?? 0) + it.qty);
    }

    // Validate items against order lines
    const lineMap = new Map();
    for (const l of order.lines) {
      if (!lineMap.has(l.sku)) lineMap.set(l.sku, { qty: 0 });
      lineMap.get(l.sku).qty += l.qty;
    }
    for (const [sku, totalQty] of itemMap) {
      const line = lineMap.get(sku);
      if (!line) throw new RefundError(`SKU ${sku} not found in order`);
      if (totalQty > line.qty) throw new RefundError(`Cannot refund more than available for ${sku}`);
    }

    // Compute refund amounts and update running totals
    const refundRecords = [];
    let refundedTotalCents = 0;
    for (const l of order.lines) {
      const lineQty = itemMap.get(l.sku);
      if (!lineQty) continue;
      const netCents = l.netCents;
      const taxCents = l.taxCents;
      let refundedNetCents, refundedTaxCents;
      if (l.qty - lineQty === 0) {
