        refundedTaxCents = roundHalfAwayFromZero(taxCents * lineQty / l.qty);
      }
      l.refundedQty = (l.refundedQty ?? 0) + lineQty;
      l.refundedNetCents = (l.refundedNetCents ?? 0) + refundedNetCents;
      l.refundedTaxCents = (l.refundedTaxCents ?? 0) + refundedTaxCents;
      const rTotal = refundedNetCents + refundedTaxCents;
      refundedTotalCents += rTotal;
      refundRecords.push({
        id: `R${String(this.refundNo++).padStart(4, '0')}`,
        orderId,
        date,
        lines: [{ sku: l.sku, qty: lineQty, netCents: refundedNetCents, taxCents: refundedTaxCents, totalCents: rTotal }],
        totalCents: rTotal,
      });
    }

    // Restock if requested
    if (restock) {
      for (const l of order.lines) {
        this.inventory.release(l.sku, itemMap.get(l.sku));
      }
    }

    // Update order status
    const allRefunded = refundRecords.every(r => r.totalCents === 0);
    order.status = allRefunded ? 'refunded' : 'partially_refunded';

    // Append refund records
    this.refunds.push(...refundRecords);

    return refundRecords[0];
  }
}

module.exports = { OrderService, OrderError };
